/////////////////////////////////
// cp_load_access_fault
//   Test every type of compressed load to a faulting address and check that each one throws a load access fault.
/////////////////////////////////

# Testcase: c.lw with faulting address
  LI(x13, RVMODEL_ACCESS_FAULT_ADDRESS)
ExceptionsZc_cg_cp_load_access_fault_c_lw_fault:
  c.lw x8, 0(x13)
  #Faulting compressed instruction can land on or 2 bytes past a 4 byte boundary (Resume address is 8 or 6 bytes after instr addr); Three c.nops provide 6 bytes buffer
  c.nop
  c.nop
  c.nop

# Testcase: c.lwsp with faulting address
  mv x10, sp
  LI(sp, RVMODEL_ACCESS_FAULT_ADDRESS)
ExceptionsZc_cg_cp_load_access_fault_c_lwsp_fault:
  c.lwsp x11, 0(sp)
  #Faulting compressed instruction can land on or 2 bytes past a 4 byte boundary (Resume address is 8 or 6 bytes after instr addr); Three c.nops provide 6 bytes buffer
  c.nop
  c.nop
  c.nop
  mv sp, x10

